+/** Preparation-only control plane. No Slack, model, browser, or container execution. */
+export const OWNER_ALIASES = ["tanishq", "sahan", "nishank"] as const;
+export type OwnerAlias = (typeof OWNER_ALIASES)[number];
+export const POOL_NAME = "clanker-control-v1";
+export const HARD_SLOT_LIMIT = 3;
+
+export interface Settings {
+  PREP_ADMIN_ENABLED?: string;
+  CONTROL_ADMIN_SECRET?: string;
+  SLACK_WORKSPACE_ID?: string;
+  OWNER_MEMBER_IDS?: string;
+  MAX_RUNTIME_SLOTS?: string;
+}
+export interface Policy {
+  workspaceId: string;
+  owners: Partial<Record<OwnerAlias, string>>;
+  maxSlots: number;
+}
+export interface Reservation {
+  owner: OwnerAlias;
+  workspaceId: string;
+  memberId: string;
+  reservationId: string;
+  generation: number;
+  state: "reserved";
+}
+export interface Registry {
+  version: 1;
+  generation: number;
+  reservations: Reservation[];
+}
+export type Command =
+  | { kind: "list" }
+  | { kind: "reserve"; owner: OwnerAlias }
+  | { kind: "cancel-reservation"; owner: OwnerAlias; reservationId: string; generation: number };
+export interface Result { status: number; body: unknown; registry?: Registry }
+
+export function response(status: number, body: unknown): Response {
+  return new Response(JSON.stringify(body), {
+    status,
+    headers: { "content-type": "application/json", "cache-control": "no-store" },
+  });
+}
+
+export function policyFrom(env: Settings): Policy | undefined {
+  if (env.PREP_ADMIN_ENABLED !== "true") return undefined;
+  if (!/^T[A-Z0-9]{6,}$/.test(env.SLACK_WORKSPACE_ID ?? "")) return undefined;
+  const maxSlots = Number(env.MAX_RUNTIME_SLOTS ?? "3");
+  if (!Number.isInteger(maxSlots) || maxSlots < 1 || maxSlots > HARD_SLOT_LIMIT) return undefined;
+  let owners: unknown;
+  try { owners = JSON.parse(env.OWNER_MEMBER_IDS ?? "{}"); } catch { return undefined; }
+  if (!owners || typeof owners !== "object" || Array.isArray(owners)) return undefined;
+  const pairs = Object.entries(owners);
+  if (!pairs.length || pairs.length > HARD_SLOT_LIMIT) return undefined;
+  if (pairs.some(([alias, id]) => !OWNER_ALIASES.includes(alias as OwnerAlias)
+    || typeof id !== "string" || !/^U[A-Z0-9]{6,}$/.test(id))) return undefined;
+  if (new Set(pairs.map(([, id]) => id)).size !== pairs.length) return undefined;
+  return { workspaceId: env.SLACK_WORKSPACE_ID!, owners: owners as Policy["owners"], maxSlots };
+}
+
+export async function authorized(request: Request, env: Settings): Promise<boolean> {
+  // Deliberately an operator-only bearer surface; this is NOT Slack identity verification.
+  const secret = env.CONTROL_ADMIN_SECRET;
+  if (!policyFrom(env) || !secret || secret.length < 32 || secret.startsWith("REPLACE_")) return false;
+  if (new URL(request.url).protocol !== "https:" || request.headers.has("origin")) return false;
+  const supplied = request.headers.get("authorization") ?? "";
+  if (supplied.length > 1024) return false;
+  const encode = new TextEncoder();
+  const [actual, expected] = await Promise.all([
+    crypto.subtle.digest("SHA-256", encode.encode(supplied)),
+    crypto.subtle.digest("SHA-256", encode.encode(`Bearer ${secret}`)),
+  ]);
+  const a = new Uint8Array(actual), b = new Uint8Array(expected);
+  let diff = 0;
+  for (let i = 0; i < a.length; i++) diff |= a[i]! ^ b[i]!;
+  return diff === 0;
+}
+
+export async function commandFrom(request: Request): Promise<Command | undefined> {
+  const url = new URL(request.url);
+  if (url.search || url.pathname !== "/admin/reservations") return undefined;
+  if (request.method === "GET") return { kind: "list" };
+  if (!["POST", "DELETE"].includes(request.method)) return undefined;
+  if (request.headers.get("content-type")?.split(";")[0]?.trim() !== "application/json") return undefined;
+  // Bound bodies while streaming, including requests without Content-Length.
+  const reader = request.body?.getReader();
+  if (!reader) return undefined;
+  const chunks: Uint8Array[] = [];
+  let size = 0;
+  while (true) {
+    const { value, done } = await reader.read();
+    if (done) break;
+    size += value.byteLength;
+    if (size > 1024) { await reader.cancel(); return undefined; }
+    chunks.push(value);
+  }
+  const bytes = new Uint8Array(size);
+  let offset = 0;
+  for (const chunk of chunks) { bytes.set(chunk, offset); offset += chunk.byteLength; }
+  let body: unknown;
+  try { body = JSON.parse(new TextDecoder("utf-8", { fatal: true }).decode(bytes)); } catch { return undefined; }
+  if (!body || typeof body !== "object" || Array.isArray(body)) return undefined;
+  const value = body as Record<string, unknown>;
+  if (!OWNER_ALIASES.includes(value.owner as OwnerAlias)) return undefined;
+  const owner = value.owner as OwnerAlias;
+  if (request.method === "POST" && Object.keys(value).length === 1) return { kind: "reserve", owner };
+  if (request.method === "DELETE" && Object.keys(value).sort().join(",") === "generation,owner,reservationId"
+    && typeof value.reservationId === "string" && /^[a-f0-9-]{36}$/.test(value.reservationId)
+    && Number.isSafeInteger(value.generation) && Number(value.generation) > 0) {
+    return { kind: "cancel-reservation", owner, reservationId: value.reservationId, generation: Number(value.generation) };
+  }
+  return undefined;
+}
+
+export function emptyRegistry(): Registry { return { version: 1, generation: 0, reservations: [] }; }
+
+export function validRegistry(value: unknown): value is Registry {
+  if (!value || typeof value !== "object") return false;
+  const r = value as Registry;
+  if (r.version !== 1 || !Number.isSafeInteger(r.generation) || r.generation < 0
+    || !Array.isArray(r.reservations) || r.reservations.length > HARD_SLOT_LIMIT) return false;
+  const ids = new Set(), owners = new Set();
+  for (const row of r.reservations) {
+    if (!row || row.state !== "reserved" || !OWNER_ALIASES.includes(row.owner)
+      || typeof row.reservationId !== "string" || !/^[a-f0-9-]{36}$/.test(row.reservationId)
+      || !/^T[A-Z0-9]{6,}$/.test(row.workspaceId) || !/^U[A-Z0-9]{6,}$/.test(row.memberId)
+      || !Number.isSafeInteger(row.generation) || row.generation < 1 || row.generation > r.generation
+      || ids.has(row.reservationId) || owners.has(row.owner)) return false;
+    ids.add(row.reservationId); owners.add(row.owner);
+  }
+  return true;
+}
+
+export function transition(registry: Registry, command: Command, policy: Policy,
+  uuid: () => string = () => crypto.randomUUID()): Result {
+  if (!validRegistry(registry)) return { status: 503, body: { error: "registry_requires_reconciliation" } };
+  if (command.kind === "list") return { status: 200, body: { ...registry, executionImplemented: false } };
+  const memberId = policy.owners[command.owner];
+  if (!memberId) return { status: 403, body: { error: "owner_not_admitted" } };
+  const existing = registry.reservations.find(row => row.owner === command.owner);
+  if (command.kind === "cancel-reservation") {
+    if (!existing || existing.reservationId !== command.reservationId || existing.generation !== command.generation)
+      return { status: 409, body: { error: "reservation_mismatch" } };
+    // Safe only because this candidate NEVER starts execution. Future running records must not use this path.
+    const next = { ...registry, reservations: registry.reservations.filter(row => row !== existing) };
+    return { status: 200, body: { cancelled: true }, registry: next };
+  }
+  if (existing) {
+    if (existing.workspaceId !== policy.workspaceId || existing.memberId !== memberId)
+      return { status: 409, body: { error: "owner_binding_changed_requires_reconciliation" } };
+    return { status: 200, body: existing };
+  }
+  if (registry.reservations.length >= policy.maxSlots) return { status: 409, body: { error: "capacity_reached" } };
+  if (registry.generation === Number.MAX_SAFE_INTEGER) return { status: 503, body: { error: "generation_exhausted" } };
+  const row: Reservation = { owner: command.owner, workspaceId: policy.workspaceId, memberId,
+    reservationId: uuid(), generation: registry.generation + 1, state: "reserved" };
+  const next: Registry = { ...registry, generation: row.generation, reservations: [...registry.reservations, row] };
+  if (!validRegistry(next)) return { status: 503, body: { error: "invalid_allocation" } };
+  return { status: 201, body: row, registry: next };
+}
